    template = Counter(patterns).most_common(1)[0][0]
    out = [row[:] for row in grid]
    marker_rows = [r for r in range(m) if all(marker[r][c] for c in range(m))]
    marker_cols = [c for c in range(m) if all(marker[r][c] for r in range(m))]
