        candidates = [j for j in range(m) if tuple(template[j][c] for c in known) == observed]
        if candidates:
            row_match[r] = r if r in candidates else candidates[0]
        else:
            row_match[r] = r
    # Remove the 3 marker, then place a copy in matching positions of a vertical marker column.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0
    if vertical:
        for r in range(m):
            if r not in row_match:
